// Ensure synthetic ports generated by Forja65 contain a functional control A/B verifier.
'use strict';
const F=require('../forja65-core.js');
const cp=require('node:child_process'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const rom=F.loadRom(F.makeSyntheticRom(),'qa-controls.sfc');
const files=F.generateProject(rom,F.analyze(rom,512));
const qa=files['tools/gameplay_controls_qa.py'];
if(!qa || !qa.includes('def validate(') || !qa.includes('outside_piece_roi')) throw Error('Generated project missing controls QA');
const d=fs.mkdtempSync(path.join(os.tmpdir(),'forja-controls-qa-'));
try{
 fs.mkdirSync(path.join(d,'tools'));fs.mkdirSync(path.join(d,'tests'));
 fs.writeFileSync(path.join(d,'tools','gameplay_controls_qa.py'),qa);
 fs.copyFileSync(path.join(__dirname,'test_gameplay_controls_qa.py'),path.join(d,'tests','test_gameplay_controls_qa.py'));
 cp.execFileSync(process.env.PYTHON||'python3',[path.join(d,'tests','test_gameplay_controls_qa.py')],{stdio:'inherit'});
 console.log('FORJA65_CONTROLS_QA_GENERATION_PASS');
}finally{fs.rmSync(d,{recursive:true,force:true});}
